55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
68	
69	const quotePremium = (items: Item[]): number => {
70	  const policyBase = items.reduce(
71	    (sum, item) => sum + itemBasePremium(item),
72	    0,
73	  );
74	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
75	  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
76	};
77	
78	const runStep = (step: Step): StepResult => ({
79	  premium: quotePremium((step as QuoteStep).items),
80	});
81	
82	export const runScenario = (scenario: Scenario): ScenarioResult => ({
83	  results: scenario.steps.map(runStep),
84	});
